template.script:
// ── Anti-clickjacking ──────────────────────────────────────────
if (self === top) {
    var ackStyle = document.getElementById('antiClickjack');
    if (ackStyle) ackStyle.parentNode.removeChild(ackStyle);
} else {
    top.location = self.location;
}

// ── Values injected by Odoo ────────────────────────────────────
const MCB_SESSION_ID  = "";
const MCB_TX_REF      = "";

// ── PaymentSession configuration (MCB session.js) ──────────────
PaymentSession.configure({
    session: MCB_SESSION_ID,
    fields: {
        card: {
            number:       "#mcb-card-number",
            securityCode: "#mcb-security-code",
            expiryMonth:  "#mcb-expiry-month",
            expiryYear:   "#mcb-expiry-year",
            nameOnCard:   "#mcb-cardholder-name"
        }
    },
    frameEmbeddingMitigation: ["javascript"],
    callbacks: {
        initialized: function(response) {
            if (response.status !== "ok") {
                mcbShowError("Initialisation error. Please refresh the page.");
            }
        },
        formSessionUpdate: function(response) {
            mcbHandleSessionUpdate(response);
        }
    },
    interaction: {
        displayControl: {
            formatCard: "EMBOSSED",
            invalidFieldCharacters: "REJECT"
        }
    }
});

// ── Real-time validation ───────────────────────────────────────
PaymentSession.onBlur(
    ["card.number","card.nameOnCard","card.securityCode","card.expiryYear","card.expiryMonth"],
    function(selector, role) {
        PaymentSession.validate('card', function(result) {
            const fieldMap = {
                'card.number':       'mcb-card-number',
                'card.nameOnCard':   'mcb-cardholder-name',
                'card.securityCode': 'mcb-security-code',
                'card.expiryMonth':  'mcb-expiry-month',
                'card.expiryYear':   'mcb-expiry-year',
            };
            const id = fieldMap[role];
            if (!id) return;
            const el = document.getElementById(id);
            if (!el) return;
            const isValid = result.card[role] && result.card[role].isValid;
            el.classList.toggle('is-valid',   !!isValid);
            el.classList.toggle('is-invalid', !isValid);
        });
    }
);

// ── Payment trigger ────────────────────────────────────────────
function mcbInitiatePayment() {
    mcbClearErrors();
    PaymentSession.updateSessionFromForm('card');
}

// ── updateSessionFromForm callback ─────────────────────────────
function mcbHandleSessionUpdate(response) {
    if (!response.status) {
        mcbShowError("Session error. Please try again.");
        return;
    }
    if (response.status === "ok") {
        mcbSubmitPayment(response.session.id);
    } else if (response.status === "fields_in_error") {
        const err = response.errors;
        if (err.cardNumber)    mcbFieldError('mcb-card-number-error',    'Invalid card number.');
        if (err.expiryMonth)   mcbFieldError('mcb-expiry-error',         'Invalid expiry month.');
        if (err.expiryYear)    mcbFieldError('mcb-expiry-error',         'Invalid expiry year.');
        if (err.securityCode)  mcbFieldError('mcb-security-code-error',  'Invalid security code.');
    } else if (response.status === "request_timeout") {
        mcbShowError("Request timed out. Please try again.");
    } else {
        mcbShowError("System error. Please try again.");
    }
}

// ── Server-to-server submission ────────────────────────────────
function mcbSubmitPayment(sessionId) {
    mcbShowLoading(true);
    // Odoo 18: use fetch with JSON-RPC 2.0
    fetch('/payment/mcb/pay', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'X-Requested-With': 'XMLHttpRequest',
        },
        body: JSON.stringify({
            jsonrpc: '2.0', method: 'call', id: 1,
            params: { session_id: sessionId, reference: MCB_TX_REF }
        })
    })
    .then(r => r.json())
    .then(data => {
        mcbShowLoading(false);
        const res = data.result || data;
        if (res.success) {
            window.location.href = res.redirect_url || '/payment/status';
        } else {
            mcbShowError(res.error || 'Payment failed. Please try again.');
        }
    })
    .catch(err => {
        mcbShowLoading(false);
        mcbShowError('Connection error. Please try again.');
        console.error('MCB pay error:', err);
    });
}

// ── UI utilities ───────────────────────────────────────────────
function mcbShowError(msg) {
    document.getElementById('mcb-payment-error-message').textContent = msg;
    document.getElementById('mcb-payment-error').classList.remove('d-none');
}
function mcbFieldError(id, msg) {
    const el = document.getElementById(id);
    if (el) el.textContent = msg;
}
function mcbClearErrors() {
    document.getElementById('mcb-payment-error').classList.add('d-none');
    document.querySelectorAll('[id$="-error"]').forEach(el => el.textContent = '');
    document.querySelectorAll('.mcb-hosted-field').forEach(el => {
        el.classList.remove('is-valid','is-invalid');
    });
}
function mcbShowLoading(show) {
    const btn     = document.getElementById('mcb-pay-button');
    const loading = document.getElementById('mcb-loading');
    btn.disabled  = show;
    btn.innerHTML = show
        ? 'Processing...'
        : 'Pay now';
    loading.classList.toggle('d-none', !show);
}
